// Independent verification of two trust questions:
// 1. Was routing computed correctly? Recompute every stored route from stored
//    fields with the SAME rule as Build CRM Row, then diff.
// 2. Did Claude invent anything? A complaint or quote can only exist if the
//    business has reviews. Any complaint on a 0-review row is fabricated.
try {
  var v = ($input.first().json || {}).values || [];
  if (v.length < 2) { return [{ json: { error: 'no rows' } }]; }
  var H = v[0], I = {};
  for (var h = 0; h < H.length; h++) { I[String(H[h]).trim()] = h; }
  function c(r, n) { var i = I[n]; if (i === undefined) { return ''; } var x = r[i]; return (x === undefined || x === null) ? '' : String(x).trim(); }
  function N(r, n) { var x = c(r, n); if (x === '') { return 0; } var y = Number(x); return isNaN(y) ? 0 : y; }

  // Kept in lockstep with isCallComplaint() in '📋 Build CRM Row' (LEVER 4).
  var KW = ['call','phone','response','respons','unrespon','respond','reply','answer','rang','reach','voicemail','contact','get back','get hold','get through','pickup','pick up','available','message','communic','follow','appointment','schedul','no-show','no show','turn up','turned up','show up','showed up','never came','never turned','chase','chasing','ignore','missed'];
  function isCall(x) { if (!x) { return false; } var s = String(x).toLowerCase(); for (var i = 0; i < KW.length; i++) { if (s.indexOf(KW[i]) !== -1) { return true; } } return false; }
  function route(p, cr, rc, tc, bq) {
    var gap = cr - rc;
    // LEVER 3 mirrored: P2 leads with a dominant gap also qualify for A-lite.
    if ((p === '1' && gap >= 10) || gap >= 30) { if (tc && isCall(tc)) { return 'A'; } if (bq) { return 'A-v2'; } return 'A-lite'; }
    if (tc && isCall(tc)) { return 'B'; }
    return 'D';
  }

  var rows = v.slice(1);
  var mismatch = 0, samples = [], byPair = {};
  var halluc = { complaintNoReviews: 0, quoteNoReviews: 0, complaintNoGoogle: 0, examples: [] };
  var complaintNotCall = 0, complaintNotCallSamples = [];

  for (var r = 0; r < rows.length; r++) {
    var row = rows[r];
    var stored = c(row, 'Template Route');
    var tc = c(row, 'Top Complaint');
    var bq = c(row, 'Best Review Quote');
    var rc = N(row, 'Review Count');
    var cr = N(row, 'Competitor Reviews');
    var p = c(row, 'Priority');

    var expect = route(p, cr, rc, tc, bq);
    if (expect !== stored) {
      mismatch++;
      var pair = stored + '->' + expect;
      byPair[pair] = (byPair[pair] || 0) + 1;
      if (samples.length < 8) {
        samples.push({ row: r + 2, company: c(row, 'Company Name'), stored: stored, recomputed: expect, priority: p, reviewCount: rc, competitorReviews: cr, gap: cr - rc, hasComplaint: tc !== '', hasQuote: bq !== '' });
      }
    }

    if (tc !== '' && rc === 0) { halluc.complaintNoReviews++; if (halluc.examples.length < 5) { halluc.examples.push({ row: r + 2, company: c(row, 'Company Name'), complaint: tc, reviewCount: rc }); } }
    if (bq !== '' && rc === 0) { halluc.quoteNoReviews++; }
    if (tc !== '' && c(row, 'Google Rating') === '') { halluc.complaintNoGoogle++; }

    if (tc !== '' && !isCall(tc)) { complaintNotCall++; if (complaintNotCallSamples.length < 10) { complaintNotCallSamples.push({ company: c(row, 'Company Name'), complaint: tc, stored: stored }); } }
  }

  return [{ json: {
    rowsAudited: rows.length,
    routing: { mismatches: mismatch, verdict: mismatch === 0 ? 'PASS - every stored route matches a clean recomputation' : 'FAIL', byTransition: byPair, samples: samples },
    grounding: { verdict: (halluc.complaintNoReviews === 0 && halluc.quoteNoReviews === 0) ? 'PASS - no complaint or quote exists on a 0-review business' : 'FAIL', complaintOnZeroReviewRows: halluc.complaintNoReviews, quoteOnZeroReviewRows: halluc.quoteNoReviews, complaintWithoutGoogleData: halluc.complaintNoGoogle, examples: halluc.examples },
    wastedComplaints: { count: complaintNotCall, note: 'Leads WITH a real complaint that is not call-related. Build CRM Row only routes call-related complaints to A or B, so these fall to D despite having the strongest personal signal.', samples: complaintNotCallSamples }
  }}];
} catch (e) { return [{ json: { error: 'Audit failed: ' + e.message } }]; }
